#include "mgl_test.h"

/* dEQP-GL45-ES31.functional.debug.negative_coverage.get_error.advanced_blend:
 * GL_INVALID_OPERATION must be generated by a draw when
 *  (a) blending is enabled, the blend equation is an advanced equation and the
 *      fragment shader's blend_support_* qualifier doesn't cover it,
 *  (b) blending is enabled, an advanced equation is set and there is more than
 *      one active draw buffer (no NVX_blend_equation_advanced_multi_draw_buffers).
 * dEQP draws with count == 0, so the checks must run for zero-vertex draws too. */

static const char *const vs_src =
    "#version 450 core\n"
    "void main() { gl_Position = vec4(0.0); }\n";

static const char *fs_qual(const char *qual)
{
    static char buf[256];
    snprintf(buf, sizeof buf,
             "#version 450 core\n"
             "#extension GL_KHR_blend_equation_advanced : enable\n"
             "layout(%s) out;\n"
             "layout(location=0) out vec4 o_color;\n"
             "void main() { o_color = vec4(0); }\n", qual);
    return buf;
}

static GLuint prog_with_qual(const char *qual)
{
    const char *fs = fs_qual(qual);
    GLuint p = glCreateProgram();
    GLuint v = glCreateShader(GL_VERTEX_SHADER), f = glCreateShader(GL_FRAGMENT_SHADER);
    glShaderSource(v, 1, &vs_src, NULL); glCompileShader(v);
    glShaderSource(f, 1, &fs, NULL); glCompileShader(f);
    glAttachShader(p, v); glAttachShader(p, f);
    glLinkProgram(p);
    GLint ok = 0; glGetProgramiv(p, GL_LINK_STATUS, &ok);
    EXPECT_EQ_INT(ok, 1);
    glDeleteShader(v); glDeleteShader(f);
    return p;
}

TEST(advblend_qualifier_mismatch_zero_count)
{
    GLuint vao;
    glGenVertexArrays(1, &vao);
    glBindVertexArray(vao);
    GLuint p_mul = prog_with_qual("blend_support_multiply");
    glUseProgram(p_mul);
    glEnable(GL_BLEND);
    glBlendEquation(GL_HSL_COLOR_KHR);
    EXPECT_NO_GL_ERROR();

    /* count 0 — dEQP's shape: the error must still be reported */
    glDrawElements(GL_TRIANGLES, 0, GL_UNSIGNED_INT, NULL);
    EXPECT_GL_ERROR(GL_INVALID_OPERATION);

    glDrawArrays(GL_TRIANGLES, 0, 0);
    EXPECT_GL_ERROR(GL_INVALID_OPERATION);

    /* blending disabled: no error */
    glDisable(GL_BLEND);
    glDrawElements(GL_TRIANGLES, 0, GL_UNSIGNED_INT, NULL);
    EXPECT_NO_GL_ERROR();

    /* blending enabled again, matching equation: no error */
    glEnable(GL_BLEND);
    glBlendEquation(GL_MULTIPLY_KHR);
    glDrawElements(GL_TRIANGLES, 0, GL_UNSIGNED_INT, NULL);
    EXPECT_NO_GL_ERROR();

    /* basic equation with mismatched qualifier: no error */
    glBlendEquation(GL_FUNC_ADD);
    glDrawElements(GL_TRIANGLES, 0, GL_UNSIGNED_INT, NULL);
    EXPECT_NO_GL_ERROR();

    /* all_equations qualifier accepts everything */
    GLuint p_all = prog_with_qual("blend_support_all_equations");
    glUseProgram(p_all);
    glBlendEquation(GL_HSL_LUMINOSITY_KHR);
    glDrawElements(GL_TRIANGLES, 0, GL_UNSIGNED_INT, NULL);
    EXPECT_NO_GL_ERROR();

    glDisable(GL_BLEND);
    glDeleteProgram(p_mul);
    glDeleteProgram(p_all);
    glDeleteVertexArrays(1, &vao);
}

TEST(advblend_multiple_draw_buffers)
{
    GLuint vao, tex, fbo;
    glGenVertexArrays(1, &vao);
    glBindVertexArray(vao);
    glGenTextures(1, &tex);
    glBindTexture(GL_TEXTURE_2D, tex);
    glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA8, 32, 32, 0, GL_RGBA, GL_UNSIGNED_BYTE, NULL);
    glGenFramebuffers(1, &fbo);
    glBindFramebuffer(GL_FRAMEBUFFER, fbo);
    glFramebufferTexture2D(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, GL_TEXTURE_2D, tex, 0);
    EXPECT_GL_ERROR(GL_NO_ERROR);

    GLuint p_mul = prog_with_qual("blend_support_multiply");
    glUseProgram(p_mul);
    glEnable(GL_BLEND);
    glBlendEquation(GL_MULTIPLY_KHR);
    const GLenum bufs[2] = { GL_COLOR_ATTACHMENT0, GL_COLOR_ATTACHMENT1 };
    glDrawBuffers(2, bufs);
    EXPECT_NO_GL_ERROR();
    glDrawElements(GL_TRIANGLES, 0, GL_UNSIGNED_INT, NULL);
    EXPECT_GL_ERROR(GL_INVALID_OPERATION);

    /* one draw buffer again: no error (equation matches the qualifier) */
    glDrawBuffers(1, bufs);
    glDrawElements(GL_TRIANGLES, 0, GL_UNSIGNED_INT, NULL);
    EXPECT_NO_GL_ERROR();

    glDisable(GL_BLEND);
    glBindFramebuffer(GL_FRAMEBUFFER, 0);
    glDeleteProgram(p_mul);
    glDeleteFramebuffers(1, &fbo);
    glDeleteTextures(1, &tex);
    glDeleteVertexArrays(1, &vao);
}

int main(void)
{
    RUN(advblend_qualifier_mismatch_zero_count);
    RUN(advblend_multiple_draw_buffers);
    return mgl_test_summary();
}
